local themeIgnored=setmetatable({},{__mode="k"})
local themeBindings=setmetatable({},{__mode="k"})
local themeRefreshers={}
local themeTweens=setmetatable({},{__mode="k"})
local syncThemeControls
local function validHex(value)
    if type(value)~="string" then return nil end
    local clean=value:gsub("%s",""):gsub("^#",""):upper()
    if #clean~=6 or clean:find("[^%x]") then return nil end
    return clean
end
local function make(class, props, parent)
    local object = Instance.new(class)
    for k, v in pairs(props) do
        if k~="ThemeIgnore" then
            object[k] = v
            if typeof(v)=="Color3" and (k=="BackgroundColor3" or k=="TextColor3" or k=="Color"
                or k=="ImageColor3" or k=="PlaceholderColor3" or k=="ScrollBarImageColor3") then
                for name,color in pairs(C) do
                    if name~="onAccent" and color==v then
                        themeBindings[object]=themeBindings[object] or {}
                        themeBindings[object][k]=name
                        break
                    end
                end
            end
        end
    end
    if props.ThemeIgnore then themeIgnored[object]=true end
    object.Parent = parent
    return object
end
local function round(object, radius)
    make("UICorner", {CornerRadius = UDim.new(0, radius)}, object)
end
local function bindTheme(object,property,token)
    themeBindings[object]=themeBindings[object] or {}
    themeBindings[object][property]=token
    local tween=themeTweens[object]
    if tween then tween:Cancel() themeTweens[object]=nil end
end
local function text(parent, value, x, y, w, h, size, color, bold)
    return make("TextLabel", {
        BackgroundTransparency = 1, Position = UDim2.fromOffset(x,y),
        Size = UDim2.fromOffset(w,h), Text = value, TextSize = size,
        TextColor3 = color or C.text, Font = bold and Enum.Font.GothamBold or Enum.Font.Gotham,
        TextXAlignment = Enum.TextXAlignment.Left
    }, parent)
end
local gui = make("ScreenGui", {Name="NoLimitPanel", ResetOnSpawn=false,
    ZIndexBehavior=Enum.ZIndexBehavior.Sibling, DisplayOrder=100}, playerGui)
local function applyTheme(value,animate)
    local chosen=themes[value] and value or nil
    if not chosen then
        local legacy=validHex(value)
        if not legacy then return false end
        local color=fromHex(legacy)
        local distance=math.huge
        for _,id in ipairs(themeOrder) do
            local candidate=themes[id].colors.accent
            local d=(candidate.R-color.R)^2+(candidate.G-color.G)^2+(candidate.B-color.B)^2
            if d<distance then chosen,distance=id,d end
        end
    end
    themeId=chosen
    themeHex=themes[chosen].hex
    for name,color in pairs(themes[chosen].colors) do C[name]=color end
    for _,object in ipairs(gui:GetDescendants()) do
        local ignored=false
        local ancestor=object
        while ancestor and ancestor~=gui do
            if themeIgnored[ancestor] then ignored=true break end
            ancestor=ancestor.Parent
        end
        if not ignored then
            local previous=themeTweens[object]
            if previous then previous:Cancel() end
            local goals={}
            for property,name in pairs(themeBindings[object] or {}) do goals[property]=C[name] end
            if next(goals) then
                if animate==false then
                    for property,value in pairs(goals) do object[property]=value end
                else
                    local tween=TweenService:Create(object,TweenInfo.new(0.22,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),goals)
                    themeTweens[object]=tween
                    tween:Play()
                end
            end
            if object:IsA("UIGradient") then
                object.Color=ColorSequence.new(C.panel:Lerp(C.accent,0.18),C.background)
            end
            if object:IsA("ScrollingFrame") then object.ScrollBarImageColor3=C.line end
        end
    end
    for _,refresh in ipairs(themeRefreshers) do refresh() end
    if syncThemeControls then syncThemeControls() end
    return true
end
