do
    local crownViews,backdrops={},{}
    local crownAsset,animationAssets
    local index,elapsed=1,0
    local loader=type(getcustomasset)=="function" and getcustomasset
        or (type(getsynasset)=="function" and getsynasset or nil)
    local map={}
    local alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    for i=1,#alphabet do map[alphabet:sub(i,i)]=i-1 end
    local function decode(encoded)
        local result={}
        for i=1,#encoded,4 do
            local a,b,c,d=encoded:sub(i,i),encoded:sub(i+1,i+1),encoded:sub(i+2,i+2),encoded:sub(i+3,i+3)
            local n=(map[a] or 0)*262144+(map[b] or 0)*4096+(map[c] or 0)*64+(map[d] or 0)
            local x,y,z=math.floor(n/65536)%256,math.floor(n/256)%256,n%256
            result[#result+1]=d~="=" and string.char(x,y,z) or (c~="=" and string.char(x,y) or string.char(x))
        end
        return table.concat(result)
    end
    local function asset(name,page)
        assert(loader and type(writefile)=="function","UI images need writefile + getcustomasset")
        local path=page and mediaData.files[name][page] or mediaData.files[name]
        local encoded=page and mediaData[name][page] or mediaData[name]
        local exists=false
        if type(isfile)=="function" then
            local ok,value=pcall(isfile,path)
            exists=ok and value==true
        end
        if not exists then writefile(path,decode(encoded)) end
        local uri=loader(path)
        assert(type(uri)=="string" and #uri>0,"Local UI image unavailable")
        local failed=false
        game:GetService("ContentProvider"):PreloadAsync({uri},function(_,status)
            if status~=Enum.AssetFetchStatus.Success then failed=true end
        end)
        assert(not failed,"Local UI image failed to load")
        return uri
    end
    local function updateFrame()
        local page=math.floor((index-1)/mediaData.perPage)+1
        local localIndex=(index-1)%mediaData.perPage
        local offset=Vector2.new((localIndex%mediaData.columns)*mediaData.width,
            math.floor(localIndex/mediaData.columns)*mediaData.height)
        for _,view in ipairs(backdrops) do
            if view.image.Parent then
                if animationAssets then view.image.Image=animationAssets[page] end
                view.image.ImageRectOffset=offset
            end
        end
    end
    local function refresh()
        for _,view in ipairs(backdrops) do
            view.image.Visible=visuals.background and animationAssets~=nil
            view.veil.Visible=view.image.Visible
        end
        for _,view in ipairs(crownViews) do
            if crownAsset then view.image.Image=crownAsset end
            view.image.Visible=crownAsset~=nil
            view.fallback.Visible=crownAsset==nil
        end
    end
    visuals.attachCrown=function(parent,size)
        local large=size>40
        local dimension=large and 52 or size-4
        local position=large and UDim2.fromOffset(10,4) or UDim2.fromOffset(2,2)
        local icon=make("ImageLabel",{Position=position,Size=UDim2.fromOffset(dimension,dimension),
            BackgroundTransparency=1,Image="",ImageColor3=C.art,ScaleType=Enum.ScaleType.Fit,
            Visible=false},parent)
        local fallback=text(parent,"♛",large and 10 or 2,large and 4 or 2,dimension,dimension,
            large and 34 or 21,C.art,true)
        fallback.TextXAlignment=Enum.TextXAlignment.Center
        crownViews[#crownViews+1]={image=icon,fallback=fallback}
        refresh()
    end
    visuals.attachBackdrop=function(parent,radius)
        local image=make("ImageLabel",{Size=UDim2.fromScale(1,1),BackgroundTransparency=1,
            Image="",ImageColor3=Color3.new(1,1,1),ImageTransparency=0,ScaleType=Enum.ScaleType.Crop,
            ImageRectSize=Vector2.new(mediaData.width,mediaData.height),Visible=false,ThemeIgnore=true},parent)
        round(image,radius)
        if parent.Name=="NoLimitWindow" then
            image.Position=UDim2.fromScale(0.04,0.11)
            image.Size=UDim2.fromScale(1.12,1.12)
        end
        local veil=make("Frame",{Size=UDim2.fromScale(1,1),BackgroundColor3=C.background,
            BackgroundTransparency=1,BorderSizePixel=0,Visible=false},parent)
        round(veil,radius)
        backdrops[#backdrops+1]={image=image,veil=veil,host=parent}
        refresh()
    end
    visuals.setBackground=function(on)
        visuals.background=on==true
        refresh()
    end
    visuals.setAnimation=function(on)
        visuals.animate=on==true
        if not visuals.animate then index,elapsed=1,0 updateFrame() end
    end
    local started=false
    visuals.start=function()
        if started then return end
        started=true
        for _,name in ipairs({"crown","astronaut"}) do
            task.spawn(function()
                local ok,value=pcall(function()
                    if name=="crown" then return asset(name) end
                    local pages={}
                    for page=1,#mediaData.astronaut do
                        if not running then return nil end
                        pages[page]=asset(name,page)
                    end
                    return pages
                end)
                if not running then return end
                if ok then
                    if name=="crown" then crownAsset=value else animationAssets=value end
                    refresh()
                    updateFrame()
                else
                    warn("NoLimit "..name.." image: "..tostring(value))
                end
            end)
        end
    end
    connect(RunService.RenderStepped,function(dt)
        if not running or not visuals.background or not visuals.animate or not animationAssets then return end
        local visible=false
        for _,view in ipairs(backdrops) do
            if view.host.Visible and view.image.Visible then visible=true break end
        end
        if not visible then return end
        elapsed=elapsed+math.min(dt,0.25)
        local advanced=false
        while elapsed>=mediaData.durations[index] do
            elapsed=elapsed-mediaData.durations[index]
            index=index%mediaData.frames+1
            advanced=true
        end
        if advanced then updateFrame() end
    end)
end

end
