    for _,item in ipairs({{selected,overviewNavText,overviewAccent,"Overview"},
        {espButton,espNavText,espAccent,"ESP"},{skyButton,skyNavText,skyAccent,"Sky"},
        {settingsButton,settingsNavText,settingsAccent,"Settings"}}) do
