local function destroyMarker(record)
    for _,connection in ipairs(record.connections or {}) do connection:Disconnect() end
    if record.healthTween then record.healthTween:Cancel() end
    record.highlight:Destroy()
    record.tag:Destroy()
end
local function renderMarkerHealth(record,instant)
    local health=record.character:GetAttribute("Health")
    local maximum=record.character:GetAttribute("MaxHealth")
    local validHealth=type(health)=="number" and health==health and math.abs(health)<math.huge
    local validMaximum=type(maximum)=="number" and maximum==maximum and maximum>0 and maximum<math.huge
    local hasTitle=#record.label.Text>0
    record.healthLabel.Visible=espOptions.health
    record.healthLabel.Position=UDim2.fromOffset(0,hasTitle and 21 or 0)
    record.bar.Position=UDim2.new(0.5,-60,0,hasTitle and 43 or 23)
    record.bar.Visible=espOptions.health and validHealth and validMaximum
    record.tag.Enabled=hasTitle or espOptions.health
    if not espOptions.health then
        if record.healthTween then record.healthTween:Cancel() record.healthTween=nil end
        record.ratio=nil
        return
    end
    if not validHealth then
        record.healthLabel.Text="HP --"
        record.healthLabel.TextColor3=Color3.fromRGB(210,215,224)
        if record.healthTween then record.healthTween:Cancel() record.healthTween=nil end
        record.ratio=nil
        return
    end
    health=math.max(0,health)
    local function number(value)
        if math.abs(value-math.floor(value+0.5))<0.00001 then return tostring(math.floor(value+0.5)) end
        return string.format("%.1f",value)
    end
    record.healthLabel.Text=validMaximum and (number(health).." / "..number(maximum).." HP") or (number(health).." HP")
    local ratio=validMaximum and math.clamp(health/maximum,0,1) or 1
    local color=ratio>0.5 and Color3.fromRGB(83,216,154)
        or (ratio>0.25 and Color3.fromRGB(245,190,91) or Color3.fromRGB(245,106,117))
    record.healthLabel.TextColor3=color
    record.fill.BackgroundColor3=color
    if validMaximum and (record.ratio~=ratio or instant) then
        if record.healthTween then record.healthTween:Cancel() end
        local goal=UDim2.fromScale(ratio,1)
        if instant or record.ratio==nil then
            record.fill.Size=goal
        else
            record.healthTween=TweenService:Create(record.fill,TweenInfo.new(0.12,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),{Size=goal})
            record.healthTween:Play()
        end
        record.ratio=ratio
    elseif not validMaximum then
        if record.healthTween then record.healthTween:Cancel() record.healthTween=nil end
        record.ratio=nil
    end
end
local function clearESP()
    for player, record in pairs(markers) do
        destroyMarker(record)
        markers[player] = nil
    end
end
