local skyPresets={
    OceanDrift={name="Ocean Drift",colors={"102243","306998","6EC4C9","E7C1A7"}},
    GoldenHour={name="Golden Hour",colors={"292943","835075","E28A81","F5C27D"}},
    LavenderMist={name="Lavender Mist",colors={"252342","645E9C","AFA3D5","E7C0CD"}},
    EmeraldDusk={name="Emerald Dusk",colors={"102C35","326266","78AAA0","D8C9A0"}},
    PolarLights={name="Polar Lights",colors={"070F24","175366","4ACB9B","8E7FC7"},stars=true},
    DeepSpace={name="Deep Space",colors={"070918","25244D","4E407F","447596"},stars=true},
    VelvetPink={name="Velvet Pink",colors={"180D27","3D204A","723C73","B7779F"},stars=true}
}
local Lighting=game:GetService("Lighting")
local ContentProvider=game:GetService("ContentProvider")
local originals,clouds,saved={}, {}, false
local ownSky
local request=0
local resolved={}
local refreshSky
local assetLoader=type(getcustomasset)=="function" and getcustomasset
    or (type(getsynasset)=="function" and getsynasset or nil)
local alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local decodeMap={}
for i=1,#alphabet do decodeMap[alphabet:sub(i,i)]=i-1 end
local function decodeBase64(encoded)
    local output={}
    for i=1,#encoded,4 do
        local a,b,c,d=encoded:sub(i,i),encoded:sub(i+1,i+1),encoded:sub(i+2,i+2),encoded:sub(i+3,i+3)
        local packed=(decodeMap[a] or 0)*262144+(decodeMap[b] or 0)*4096
            +(decodeMap[c] or 0)*64+(decodeMap[d] or 0)
        local x,y,z=math.floor(packed/65536)%256,math.floor(packed/256)%256,packed%256
        output[#output+1]=d~="=" and string.char(x,y,z) or (c~="=" and string.char(x,y) or string.char(x))
    end
    return table.concat(output)
end
local function textures(id)
    if resolved[id] then return resolved[id] end
    assert(type(writefile)=="function" and assetLoader,"Executor needs writefile + getcustomasset for sky images")
    local assets={}
    for _,face in ipairs({"Bk","Dn","Ft","Lf","Rt","Up"}) do
        local file="NoLimitSky_3_"..id.."_"..face..".png"
        local exists=false
        if type(isfile)=="function" then
            local ok,value=pcall(isfile,file)
            exists=ok and value==true
        end
        if not exists then writefile(file,decodeBase64(skyImages[id][face])) end
        assets[face]=assetLoader(file)
        assert(type(assets[face])=="string" and #assets[face]>0,"Sky image could not be loaded")
    end
    resolved[id]=assets
    return assets
end
local function restoreSky()
    if ownSky then ownSky:Destroy() ownSky=nil end
    for _,record in ipairs(originals) do
        pcall(function()
            if record.object.Parent==nil then record.object.Parent=record.parent end
        end)
    end
    for _,record in ipairs(clouds) do
        pcall(function()
            if record.object.Parent and not record.object.Enabled then record.object.Enabled=record.enabled end
        end)
    end
    originals,clouds,saved={}, {}, false
end
local function captureSky()
    if saved then return end
    saved=true
    for _,object in ipairs(Lighting:GetChildren()) do
        if object:IsA("Sky") or object:IsA("Atmosphere") then
            originals[#originals+1]={object=object,parent=Lighting}
            object.Parent=nil
        end
    end
    local terrain=workspace:FindFirstChildOfClass("Terrain")
    if terrain then
        for _,object in ipairs(terrain:GetChildren()) do
            if object:IsA("Clouds") then
                clouds[#clouds+1]={object=object,enabled=object.Enabled}
                object.Enabled=false
            end
        end
    end
end
sky.valid=function(id) return type(id)=="string" and skyPresets[id]~=nil end
sky.set=function(on,id)
    if sky.valid(id) then sky.preset=id end
    request=request+1
    local version=request
    sky.enabled=on==true
    if not sky.enabled then
        restoreSky()
        if refreshSky then refreshSky() end
        return
    end
    local selected=sky.preset
    status.Text="Loading "..skyPresets[selected].name.."..."
    if refreshSky then refreshSky() end
    task.spawn(function()
        local candidate
        local ok,err=pcall(function()
            local assets=textures(selected)
            if not running or request~=version or not sky.enabled then return end
            candidate=Instance.new("Sky")
            candidate.Name="NoLimitSky"
            candidate.CelestialBodiesShown=false
            candidate.StarCount=0
            for face,asset in pairs(assets) do candidate["Skybox"..face]=asset end
            local failed=false
            ContentProvider:PreloadAsync({candidate},function(_,result)
                if result~=Enum.AssetFetchStatus.Success then failed=true end
            end)
            assert(not failed,"The executor could not display a local sky texture")
            if not running or request~=version or not sky.enabled then return end
            captureSky()
            if ownSky then ownSky:Destroy() end
            ownSky=candidate
            candidate=nil
            ownSky.Parent=Lighting
        end)
        if candidate then candidate:Destroy() end
        if not running or request~=version then return end
        if not ok then
            sky.enabled=false
            restoreSky()
            status.Text="Sky unavailable — check F9"
            warn("NoLimit sky: "..tostring(err))
        else
            status.Text=skyPresets[selected].name.." sky applied"
        end
        if refreshSky then refreshSky() end
    end)
end
sky.shutdown=function()
    request=request+1
    sky.enabled=false
    restoreSky()
end

