refreshSky=function()
    synchronizing=true
    setSkyEnabled(sky.enabled)
    synchronizing=false
    for id,card in pairs(cards) do
        local selected=id==sky.preset
        bindTheme(card.border,"Color",selected and "accent" or "line")
        bindTheme(card.name,"TextColor3",selected and "accent" or "text")
        card.border.Color=selected and C.accent or C.line
        card.border.Transparency=selected and 0 or 0.4
        card.check.Visible=selected
        card.name.TextColor3=selected and C.accent or C.text
    end
end
